const item = $input.first().json;
const rawText = item.content?.parts?.[0]?.text || item.text || item.output || "{}";
const cleanedJson = rawText.replace(/```json|```/g, "").trim();

let parsed = {};
try {
  parsed = JSON.parse(cleanedJson);
} catch (e) {
  throw new Error("Gemini did not return valid JSON: " + rawText.substring(0, 200));
}

const bnToEnDigits = (str) => {
  if (!str) return "";
  const map = {'০':'0','১':'1','২':'2','৩':'3','৪':'4','৫':'5','৬':'6','৭':'7','৮':'8','৯':'9'};
  return String(str).replace(/[০-৯]/g, d => map[d]);
};

let fileName = "uploaded_challan.pdf";
let fileId = "";
try {
  const driveData = $('Upload file').first().json;
  fileName = driveData.name || fileName;
  fileId = driveData.id || "";
} catch (err) {}

const cleanAmount = bnToEnDigits(parsed.amount).replace(/[^0-9.]/g, "");
const cleanChallanNo = bnToEnDigits(parsed.challan_no);
const cleanDate = bnToEnDigits(parsed.date);

const sheetRow = {
  file_name: fileName,
  challan_no: cleanChallanNo,
  date: cleanDate,
  bank_name: parsed.bank_name ?? "",
  branch: parsed.branch ?? "",
  govt_office: parsed.govt_office ?? "",
  paid_through_name: parsed.paid_through_name ?? "",
  paid_on_behalf_of: parsed.paid_on_behalf_of ?? "",
  purpose_code: parsed.purpose_code ?? "",
  amount: cleanAmount,
  amount_in_words: parsed.amount_in_words ?? "",
  remarks: parsed.remarks ?? "",
  attachment_summary: parsed.attachment_summary ?? "",
  status: parsed.confidence_status ?? "VERIFIED",
  notes: parsed.verification_notes ?? "",
  metadata: JSON.stringify({ file_id: fileId, file_name: fileName, challan_no: cleanChallanNo }),
  pageContent: `File: ${fileName}\nChallan No: ${cleanChallanNo}\nDate: ${cleanDate}\nBank: ${parsed.bank_name}, ${parsed.branch}\nGovt Office: ${parsed.govt_office}\nPaid By: ${parsed.paid_through_name}\nOn Behalf Of: ${parsed.paid_on_behalf_of}\nAmount: ${cleanAmount} (${parsed.amount_in_words})\nRemarks: ${parsed.remarks}\nAttachments: ${parsed.attachment_summary}\n\nFull Content:\n${parsed.full_markdown_transcription ?? ""}`
};

return [{ json: sheetRow }];

